    "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG or ICO. Animated files export their first frame. Metadata is not copied.": "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG of ICO. Bij geanimeerde bestanden wordt het eerste frame geëxporteerd. Metadata wordt niet gekopieerd.",
    "Transparent areas become white. Animated images use only their first frame.": "Transparante gebieden worden wit. Bij geanimeerde afbeeldingen wordt alleen het eerste frame gebruikt.",
    "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG and ICO. Animated files export only their first frame. Output up to 40 megapixels.": "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG en ICO. Bij geanimeerde bestanden wordt alleen het eerste frame geëxporteerd. Uitvoer tot 40 megapixels.",
    "Convert common image formats to JPG, PNG or WebP on your device. Up to 20 files.": "Converteer veelvoorkomende afbeeldingsformaten naar JPG, PNG of WebP op uw apparaat. Maximaal 20 bestanden.",
    "Add up to 20 images. No fixed file-size cap; 20 megapixels per image. Large batches depend on your device memory.": "Voeg maximaal 20 afbeeldingen toe. Geen vaste limiet voor bestandsgrootte; 20 megapixels per afbeelding. Bij grote batches hangt het af van het geheugen van uw apparaat.",
    "Images converted. Animated files become a still frame; metadata is not copied.": "Afbeeldingen geconverteerd. Geanimeerde bestanden worden een stilstaand beeld; metadata wordt niet gekopieerd.",
    "Some files were skipped. Use a supported image format within the on-page limits.": "Sommige bestanden zijn overgeslagen. Gebruik een ondersteund afbeeldingsformaat binnen de limieten van de pagina.",
    "This image could not be decoded by your browser. Try another file or browser.": "Deze afbeelding kon niet door uw browser worden gedecodeerd. Probeer een ander bestand of een andere browser.",
    "Choose a supported image format.": "Kies een ondersteund afbeeldingsformaat.",
    "The browser does not support the selected output format.": "De browser ondersteunt het geselecteerde uitvoerformaat niet.",
    "Up to 20 images · 20 megapixels per image · no fixed file-size cap. Large batches depend on your device memory.": "Maximaal 20 afbeeldingen · 20 megapixels per afbeelding · geen vaste limiet voor bestandsgrootte. Bij grote batches hangt het af van het geheugen van uw apparaat.",
    "Choose up to 20 images.": "Kies maximaal 20 afbeeldingen.",
    "AVIF and some HEIC files may depend on browser support.": "Voor AVIF- en sommige HEIC-bestanden is mogelijk browserondersteuning vereist.",
    "AVIF and some HEIC inputs depend on browser support. Animated GIF, APNG and WebP files become a still image. SVG is rasterized, not converted into an editable vector. Metadata is not copied.": "Voor AVIF- en sommige HEIC-invoerbestanden is browserondersteuning vereist. Geanimeerde GIF-, APNG- en WebP-bestanden worden een stilstaande afbeelding. SVG wordt gerasterd, niet omgezet in een bewerkbare vector. Metadata wordt niet gekopieerd.",
    "Multi-page TIFF uses only its first page. Some TIFF compression variants may not decode.": "Bij TIFF-bestanden met meerdere pagina's wordt alleen de eerste pagina gebruikt. Sommige TIFF-compressievarianten kunnen mogelijk niet worden gedecodeerd.",
    "Choose a DOCX, XLSX or PPTX file": "Kies een DOCX-, XLSX- of PPTX-bestand.",
    "Files stay on your device. Limits: 100 MB input, 200 MB expanded data and 5,000 package parts.": "Bestanden blijven op uw apparaat staan. Limieten: 100 MB invoer, 200 MB uitgepakte gegevens en 5000 pakketonderdelen.",
    "This safely recompresses the Office package without rewriting its contents. Embedded photos are not recompressed, so the result may not be smaller. Signed, encrypted, macro-enabled and older Office files are not supported. Keep your original.": "Hiermee wordt het Office-pakket veilig opnieuw gecomprimeerd zonder de inhoud te wijzigen. Ingesloten foto's worden niet opnieuw gecomprimeerd, waardoor het resultaat mogelijk niet kleiner is. Ondertekende of versleutelde Office-bestanden, bestanden met macro's en oudere Office-bestanden worden niet ondersteund. Bewaar uw origineel.",
    "Try to reduce file size": "Probeer de bestandsgrootte te verkleinen.",
    "Processing runs locally in this browser. No upload.": "De verwerking vindt lokaal in deze browser plaats. Er vindt geen upload plaats.",
    "Recompressing the Office package on your device…": "Het Office-pakket wordt opnieuw gecomprimeerd op uw apparaat...",
    "This package is already compact. No smaller download was created.": "Dit pakket is al compact. Er is geen kleinere download gemaakt.",
    "A smaller copy is ready. Compare it and keep your original.": "Er is een kleiner exemplaar beschikbaar. Vergelijk dit met het origineel en bewaar het origineel.",
    "The file could not be safely recompressed. Your original has not changed.": "Het bestand kon niet veilig opnieuw worden gecomprimeerd. Uw origineel is ongewijzigd gebleven.",
    "Processing canceled. Your original file is unchanged.": "Verwerking geannuleerd. Uw originele bestand is ongewijzigd.",
    "Choose a modern DOCX, XLSX or PPTX file.": "Kies een modern DOCX-, XLSX- of PPTX-bestand.",
    "This file is larger than the 100 MB local processing limit.": "Dit bestand is groter dan de limiet van 100 MB voor lokale verwerking.",
    "The expanded package exceeds the 200 MB local processing limit.": "Het uitgepakte pakket overschrijdt de limiet van 200 MB voor lokale verwerking.",
    "Encrypted Office packages are not supported.": "Versleutelde Office-pakketten worden niet ondersteund.",
    "Signed or macro-enabled Office files are not supported, to avoid invalidating signatures or macros.": "Ondertekende Office-bestanden of bestanden met macro's worden niet ondersteund, om te voorkomen dat handtekeningen of macro's ongeldig worden.",
    "The selected file is not a valid modern Office document of that type.": "Het geselecteerde bestand is geen geldig modern Office-document van dat type.",
