    "Check the selected file and settings, then try again.": "Controleer het geselecteerde bestand en de instellingen en probeer het opnieuw.",
    "Up to 200 files; 100 MB total or expanded. ZIP64 and password-protected files are not supported. Large archives use device memory; a computer is recommended.": "Maximaal 200 bestanden; in totaal of uitgepakt 100 MB. ZIP64- en met een wachtwoord beveiligde bestanden worden niet ondersteund. Grote archieven gebruiken het geheugen van het apparaat; een computer wordt aanbevolen.",
    "Convert / trim": "Converteren / bijsnijden",
    "Estimate only, not a loan offer. Fees, taxes, insurance and lender terms are not included.": "Alleen een schatting, geen leningaanbod. Kosten, belastingen, verzekeringen en voorwaarden van de kredietverstrekker zijn niet inbegrepen.",
    "Illustration only; actual returns vary and are not guaranteed. Taxes, inflation and fees are excluded.": "Alleen ter illustratie; werkelijke rendementen variëren en worden niet gegarandeerd. Belastingen, inflatie en kosten zijn niet inbegrepen.",
