    "Extract selectable PDF text into Markdown with page headings. Scanned pages must be OCR-processed first; page layout and tables are not preserved.": "Extraheer selecteerbare PDF-tekst naar Markdown met paginakoppen. Gescande pagina's moeten eerst via OCR worden verwerkt; paginalay-out en tabellen blijven niet behouden.",
    "Extracts selectable text page by page. Scanned pages need OCR first; layout, tables and images are not preserved. Your file stays on this device.": "Extraheert selecteerbare tekst pagina voor pagina. Gescande pagina's vereisen eerst OCR; lay-out, tabellen en afbeeldingen blijven niet behouden. Uw bestand blijft op dit apparaat staan.",
    "Markdown conversion complete. Review the extracted text and download the file.": "Conversie naar Markdown voltooid. Controleer de geëxtraheerde tekst en download het bestand.",
    "Action": "Actie",
    "Protect PDF with a password": "PDF beveiligen met wachtwoord",
    "Remove password (current password required)": "Wachtwoord verwijderen (huidig wachtwoord vereist)",
    "Password to open the PDF": "Wachtwoord om PDF te openen",
    "Current PDF password": "Huidig ​​PDF-wachtwoord",
    "Confirm opening password": "Wachtwoord bevestigen",
    "Separate owner password": "Apart eigenaarswachtwoord",
    "Use different passwords, and keep them somewhere safe. If you lose them, this tool cannot recover them.": "Gebruik verschillende wachtwoorden en bewaar ze op een veilige plek. Als u ze kwijtraakt, kan deze tool ze niet herstellen.",
    "This removes encryption only when you know the current password. It does not bypass or guess passwords.": "Hiermee wordt de versleuteling alleen verwijderd als u het huidige wachtwoord kent. Wachtwoorden worden niet omzeild of geraden.",
    "Processing uses this device and a local PDF engine. The engine is downloaded only when you start. Files are not uploaded. A computer is recommended for large PDFs; this page accepts files up to 200 MB to help protect browser memory.": "De verwerking vindt plaats op dit apparaat met behulp van een lokale PDF-engine. De engine wordt pas gedownload wanneer u start. Er worden geen bestanden geüpload. Voor grote PDF's wordt een computer aanbevolen; deze pagina accepteert bestanden tot 200 MB om het geheugen van de browser te ontzien.",
    "Choose a PDF that will not open": "Kies een PDF die niet opent",
    "This makes a best-effort rebuilt copy and checks that a PDF reader can parse it. It cannot restore missing or destroyed page data, and some files cannot be repaired.": "Er wordt geprobeerd een herstelde kopie te maken, waarna wordt gecontroleerd of een PDF-lezer deze kan verwerken. Ontbrekende of vernietigde paginagegevens kunnen niet worden hersteld en sommige bestanden kunnen niet worden gerepareerd.",
    "The repair runs on this device. Nothing is uploaded. The local engine is downloaded only when you start. For large files, use a computer. The maximum input is 200 MB to help protect browser memory. Keep your original.": "De reparatie wordt uitgevoerd op dit apparaat. Er wordt niets geüpload. De lokale engine wordt pas gedownload wanneer u start. Gebruik een computer voor grote bestanden. De maximale bestandsgrootte is 200 MB om het geheugen van de browser te ontzien. Bewaar uw originele bestand.",
