    "Choose a file": "Bestand kiezen",
    "Office files stay on your device. Layout, formulas, charts, animations, fonts and page breaks may change. Office to PDF opens your browser’s print dialog. Use a computer for large files.": "Office-bestanden blijven op uw apparaat staan. Lay-out, formules, grafieken, animaties, lettertypen en pagina-einden kunnen veranderen. 'Office naar PDF' opent het afdrukvenster van uw browser. Gebruik een computer voor grote bestanden.",
    "PDF to Excel estimates rows from selectable text; it does not recreate formulas or tables. PDF to PowerPoint makes image-only slides. Scanned PDFs need OCR first.": "'PDF naar Excel' schat rijen op basis van selecteerbare tekst; formules of tabellen worden niet opnieuw aangemaakt. 'PDF naar PowerPoint' maakt dia's die alleen uit afbeeldingen bestaan. Voor gescande PDF's is eerst OCR vereist.",
